<script setup lang="ts">
import { ref, watch } from 'vue'; import type { AdminDataPayload } from '@/types'; import SurfaceDialog from '@/components/base/SurfaceDialog.vue'; import { DialogWidth } from '@/components/base/dialog'; import { ProxyBatchMode, parseBatchProxies, type BatchProxyDraft } from '@/features/admin/resources/proxy'; import { useAppStore } from '@/stores/app'
const props = defineProps<{ show: boolean; mode: ProxyBatchMode; submitting?: boolean }>(); const emit = defineEmits<{ close: []; create: [rows: BatchProxyDraft[]]; import: [payload: AdminDataPayload] }>(); const app = useAppStore(); const content = ref('')
function submit(): void { try { if (props.mode === ProxyBatchMode.CREATE) emit('create', parseBatchProxies(content.value)); else emit('import', JSON.parse(content.value) as AdminDataPayload) } catch (caught) { app.showError((caught as Error).message || '内容格式不正确') } }
async function chooseFile(event: Event): Promise<void> { const file = (event.target as HTMLInputElement).files?.[0]; if (file) content.value = await file.text() }
watch(() => props.show, (show) => { if (show) content.value = '' })
</script>
<template><SurfaceDialog :show="show" :title="mode === ProxyBatchMode.CREATE ? '批量创建代理' : '导入代理数据'" :description="mode === ProxyBatchMode.CREATE ? '每行一个 URL，支持 http/https/socks5/socks5h 与 user:pass@host:port。' : '导入由管理端导出的 JSON；敏感凭据只在当前编辑区短暂出现。'" :width="DialogWidth.WIDE" @close="emit('close')"><div class="resource-form-stack"><input v-if="mode === ProxyBatchMode.IMPORT" type="file" accept="application/json,.json" @change="chooseFile" /><textarea v-model="content" class="resource-code" rows="14" :placeholder="mode === ProxyBatchMode.CREATE ? 'socks5://user:pass@127.0.0.1:1080' : '{ &quot;proxies&quot;: [...] }'" /></div><template #footer><button class="button button--secondary" @click="emit('close')">取消</button><button class="button button--primary" :disabled="submitting || !content.trim()" @click="submit">{{ submitting ? '处理中…' : '确认执行' }}</button></template></SurfaceDialog></template>
